mapper.select:
SELECT id,command_id,request_hash,source_version FROM inbound_quality_revision
WHERE enterprise_id=#{ent} AND warehouse_id=#{wh} AND (id=#{inspection} OR command_id=#{command}
  OR (receipt_command_id=#{receipt} AND source_version=#{sourceVersion})) ORDER BY id LIMIT 3

mapper.update:
UPDATE inbound_receipt_quality SET source_version=#{sourceVersion},active_command_id=#{command},
  accepted_qty=#{accepted},rejected_qty=#{rejected},state='PENDING',version=version+1,updated_at=#{now}
WHERE enterprise_id=#{ent} AND warehouse_id=#{wh} AND receipt_command_id=#{receipt} AND version=#{expected}
  AND source_version=applied_version AND source_version+1=#{sourceVersion} AND putaway_qty <= #{accepted}

UPDATE inbound_receipt_quality SET applied_version=CASE WHEN #{state}='APPLIED' THEN source_version ELSE applied_version END,
  state=#{state},version=version+1,updated_at=#{now}
WHERE enterprise_id=#{ent} AND warehouse_id=#{wh} AND active_command_id=#{command} AND state='PENDING'

UPDATE inbound_receipt_quality SET putaway_qty=putaway_qty+#{qty},version=version+1,updated_at=#{now}
WHERE enterprise_id=#{ent} AND warehouse_id=#{wh} AND receipt_command_id=#{receipt} AND version=#{expected}
  AND state='APPLIED' AND source_version=applied_version AND putaway_qty+#{qty} <= accepted_qty
